new file mode 100644
index 0000000..38581c1
--- /dev/null
+++ b/signup.test.js
@@ -0,0 +1,73 @@
+const assert = require('node:assert/strict');
+const fs = require('node:fs');
+const test = require('node:test');
+const vm = require('node:vm');
+
+function formatDate(date) {
+  const year = date.getFullYear();
+  const month = String(date.getMonth() + 1).padStart(2, '0');
+  const day = String(date.getDate()).padStart(2, '0');
+  return `${year}-${month}-${day}`;
+}
+
+function loadForm() {
+  const fields = {
+    name: { id: 'name', value: 'Ada Lovelace', setAttribute() {} },
+    email: { id: 'email', value: 'ada@example.com', setAttribute() {} },
+    password: { id: 'password', value: 'correct horse battery staple', setAttribute() {} },
+    dateOfBirth: { id: 'date-of-birth', value: '', max: '', setAttribute() {} },
+  };
+  const errors = Object.fromEntries(Object.keys(fields).map((field) => [
+    `${field === 'dateOfBirth' ? 'date-of-birth' : field}-error`,
+    { hidden: true, textContent: '' },
+  ]));
+  const elementsById = {
+    name: fields.name,
+    email: fields.email,
+    password: fields.password,
+    'date-of-birth': fields.dateOfBirth,
+    ...errors,
+  };
+  let submit;
+  const form = {
+    elements: fields,
+    addEventListener(event, listener) {
+      if (event === 'submit') submit = listener;
+    },
+  };
+
+  vm.runInNewContext(fs.readFileSync('signup.js', 'utf8'), {
+    document: { getElementById: (id) => (id === 'signup-form' ? form : elementsById[id]) },
+  });
+
+  return { fields, errors, submit };
+}
+
+function submit(form) {
+  let prevented = false;
+  form.submit({ preventDefault() { prevented = true; } });
+  return prevented;
+}
+
+test('signup accepts users who are exactly 13 and rejects younger users', () => {
+  const today = new Date();
+  const thirteenthBirthday = new Date(today.getFullYear() - 13, today.getMonth(), today.getDate());
+  const younger = new Date(thirteenthBirthday);
+  younger.setDate(younger.getDate() + 1);
+  const form = loadForm();
+
+  form.fields.dateOfBirth.value = formatDate(thirteenthBirthday);
+  assert.equal(submit(form), false);
+  assert.equal(form.errors['date-of-birth-error'].textContent, '');
+
+  form.fields.dateOfBirth.value = formatDate(younger);
+  assert.equal(submit(form), true);
+  assert.equal(form.errors['date-of-birth-error'].textContent, 'You must be at least 13 years old.');
+});
+
+test('signup requires a date of birth', () => {
+  const form = loadForm();
+
+  assert.equal(submit(form), true);
+  assert.equal(form.errors['date-of-birth-error'].textContent, 'Please enter your date of birth.');
+});

