+const assert = require('node:assert/strict');
+const fs = require('node:fs');
+const test = require('node:test');
+
+const script = fs.readFileSync('signup.js', 'utf8');
+
+function submit(dateOfBirth) {
+  const fields = Object.fromEntries([
+    ['name', 'Ada Lovelace'],
+    ['email', 'ada@example.com'],
+    ['password', 'password'],
+    ['dateOfBirth', dateOfBirth],
+  ].map(([id, value]) => [id, { value, setAttribute() {} }]));
+  const errors = Object.fromEntries(Object.keys(fields).map((id) => [`${id}-error`, { hidden: true, textContent: '' }]));
+  let handler;
+  const form = { elements: fields, addEventListener(_, listener) { handler = listener; } };
+  const document = { getElementById(id) { return id === 'signup-form' ? form : fields[id] || errors[id]; } };
+  const today = new Date(2026, 9, 11);
+  class Clock extends Date {
+    constructor(...args) { super(...(args.length ? args : [today])); }
+  }
+
+  new Function('document', 'Date', script)(document, Clock);
+  let prevented = false;
+  handler({ preventDefault() { prevented = true; } });
+  return { prevented, error: errors['dateOfBirth-error'].textContent };
+}
+
+test('signup rejects birthdays less than 13 years ago', () => {
+  assert.deepEqual(submit('2013-10-11'), { prevented: false, error: '' });
+  assert.deepEqual(submit('2013-10-12'), { prevented: true, error: 'You must be at least 13 years old.' });
+  assert.deepEqual(submit(''), { prevented: true, error: 'You must be at least 13 years old.' });
+  assert.deepEqual(submit('2000-02-30'), { prevented: true, error: 'You must be at least 13 years old.' });
+});

