-Small client for the inventory upstream (`client.mjs` for raw JSON calls, `inventory.mjs` for item helpers). No dependencies; `npm test` runs `node --test`.
+Small client for the inventory upstream (`client.mjs` for raw JSON calls, `inventory.mjs` for item helpers). `fetchJson` retries dropped connections and HTTP 503 up to three times with 100/200/400 ms backoff; inject `fetch` and `sleep` for tests. No dependencies; `npm test` runs `node --test`.
diff --git a/client.mjs b/client.mjs
index 9ad81d0..c8bfeb4 100644
--- a/client.mjs
+++ b/client.mjs
@@ -0,0 +1,2 @@
+import { sleep as realSleep } from './util.mjs';
+
@@ -2,0 +5,2 @@
+const RETRY_DELAYS = [100, 200, 400];
+
@@ -12,4 +16,16 @@ export class HttpError extends Error {
-export async function fetchJson(url, { fetch = globalThis.fetch, headers = {} } = {}) {
-  const res = await fetch(url, { headers: { accept: 'application/json', ...headers } });
-  if (!res.ok) throw new HttpError(res.status, url);
-  return res.json();
+export async function fetchJson(url, { fetch = globalThis.fetch, headers = {}, sleep = realSleep } = {}) {
+  for (let attempt = 0; attempt <= RETRY_DELAYS.length; attempt++) {
+    let res;
+
+    try {
+      res = await fetch(url, { headers: { accept: 'application/json', ...headers } });
+    } catch (error) {
+      if (attempt === RETRY_DELAYS.length) throw error;
+      await sleep(RETRY_DELAYS[attempt]);
+      continue;
+    }
+
+    if (res.ok) return res.json();
+    if (res.status !== 503 || attempt === RETRY_DELAYS.length) throw new HttpError(res.status, url);
+    await sleep(RETRY_DELAYS[attempt]);
+  }
