+const assert = require('node:assert/strict');
+const fs = require('node:fs');
+const test = require('node:test');
+const vm = require('node:vm');
+
+const values = { name: 'Ada Lovelace', email: 'ada@example.com', password: 'password' };
+const fields = Object.fromEntries(Object.keys(values).concat('dob').map((id) => [id, {
+  value: values[id] || '',
+  setAttribute(name, value) { this[name] = value; },
+}]));
+const errors = Object.fromEntries(Object.keys(fields).map((id) => [`${id}-error`, {}]));
+let submit;
+const form = {
+  elements: fields,
+  addEventListener(event, listener) { if (event === 'submit') submit = listener; },
+};
+
+vm.runInNewContext(fs.readFileSync('signup.js', 'utf8'), {
+  document: { getElementById: (id) => (id === 'signup-form' ? form : fields[id] || errors[id]) },
+});
+
+function date(year, month, day) {
+  return `${year}-${String(month + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
+}
+
+function submitDob(dob) {
+  fields.dob.value = dob;
+  let prevented = false;
+  submit({ preventDefault() { prevented = true; } });
+  return { prevented, message: errors['dob-error'].textContent };
+}
+
+test('signup accepts only birth dates at least thirteen years old', () => {
+  const today = new Date();
+  const birthday = new Date(today.getFullYear() - 13, today.getMonth(), today.getDate());
+  const tooYoung = new Date(today.getFullYear() - 13, today.getMonth(), today.getDate() + 1);
+
+  assert.deepEqual(submitDob(date(birthday.getFullYear(), birthday.getMonth(), birthday.getDate())), { prevented: false, message: '' });
+  assert.deepEqual(submitDob(date(tooYoung.getFullYear(), tooYoung.getMonth(), tooYoung.getDate())), { prevented: true, message: 'You must be at least 13 years old.' });
+  assert.deepEqual(submitDob(''), { prevented: true, message: 'Please enter your date of birth.' });
+});

